import sqlite3
from contextlib import contextmanager

@contextmanager
def db_connection(path='shop.db'):
    conn = sqlite3.connect(path)
    try:
        yield conn
    finally:
        conn.close()

def execute_query(conn, sql, params=None):
    cursor = conn.cursor()
    if params:
        cursor.execute(sql, params)
    else:
        cursor.execute(sql)
    return cursor

def get_product(pid):
    with db_connection() as conn:
        cursor = execute_query(conn, 'SELECT * FROM products WHERE id = ?', (pid,))
        return cursor.fetchone()

def update_stock(pid, qty):
    with db_connection() as conn:
        execute_query(conn, 'UPDATE products SET stock = stock - ? WHERE id = ?', (qty, pid))
        conn.commit()

def list_low_stock(threshold):
    with db_connection() as conn:
        cursor = execute_query(conn, 'SELECT * FROM products WHERE stock < ?', (threshold,))
        return cursor.fetchall()
